"""Render the confirmed local architecture; generated by az-01-conductor on 2026-10-23."""

from pathlib import Path

from diagrams import Cluster, Diagram, Edge, Node
from diagrams.azure.aimachinelearning import CognitiveSearch
from diagrams.azure.compute import ContainerApps, ContainerRegistries
from diagrams.azure.database import CosmosDb
from diagrams.azure.identity import ActiveDirectory
from diagrams.azure.integration import APIManagement
from diagrams.azure.ml import AzureOpenAI, CognitiveServices
