from diagrams.azure.network import DNSPrivateZones, PrivateEndpoint
from diagrams.azure.security import KeyVaults
from diagrams.azure.storage import BlobStorage
from diagrams.onprem.client import Users

OUTPUT = Path(__file__).resolve().with_suffix("")
GRAPH = {
    "bgcolor": "white",
    "fontname": "Arial",
    "fontsize": "22",
    "pad": "0.5",
    "nodesep": "1.2",
    "ranksep": "1.05",
    "splines": "spline",
    "dpi": "150",
    "labelloc": "t",
}
NODES = {"fontname": "Arial", "fontsize": "12", "labelloc": "b"}
EDGES = {"fontname": "Arial", "fontsize": "11", "color": "#2368a0"}
CLUSTER = {"fontname": "Arial", "fontsize": "15", "margin": "24"}


def main() -> None:
    """Write a PNG beside this source without opening a viewer or contacting Azure."""
    with Diagram(
        "Adventure Works Cycles | Sales + Marketing\nConfirmed local design - NOT deployed",
        filename=str(OUTPUT),
        show=False,
        direction="TB",
        graph_attr=GRAPH,
        node_attr=NODES,
        edge_attr=EDGES,
    ):
        n_web_browser_demo = Users("Synthetic demo\nAnonymous browser")
        n_id_entra_audience = ActiveDirectory("Entra tenant\nDedicated API audience")

        with Cluster("Reference resource group | target names unselected", graph_attr=CLUSTER):
            n_edge_apim_gateway = APIManagement("APIM Standard v2\nPublic HTTPS gateway\nGateway managed identity")
            with Cluster("Proposed VNet 10.84.0.0/16 | NSGs; no address allocation yet", graph_attr=CLUSTER):
                with Cluster("APIM subnet 10.84.3.0/24", graph_attr=CLUSTER):
                    n_edge_apim_outbound = Node(
                        "Outbound integration\nMicrosoft.Web/serverFarms",
                        shape="box",
                        labelloc="c",
                        width="3.2",
                        height="0.8",
                    )
                with Cluster("Apps subnet 10.84.0.0/23 | Microsoft.App/environments", graph_attr=CLUSTER):
                    n_app_aca_backend = ContainerApps(
                        "Internal ACA environment\n.NET 10 app | 1-3 replicas\nApp managed identity"
                    )
                with Cluster("Private endpoint subnet 10.84.4.0/24", graph_attr=CLUSTER):
                    n_int_pe_services = PrivateEndpoint("Private endpoints\nSix PaaS services below")
                    n_int_dns_zones = DNSPrivateZones("Linked private DNS\nIncludes internal ACA")
                with Cluster("Agent subnet 10.84.2.0/24 | Microsoft.App/environments", graph_attr=CLUSTER):
                    n_app_agent_network = Node(
                        "Standard agent network injection\nProject managed identity\nPrivate platform data paths",
                        shape="box",
                        labelloc="c",
                        width="3.4",
                        height="1.0",
                    )

            with Cluster(
                "PaaS data planes | public access disabled; resources are not inside subnets", graph_attr=CLUSTER
            ):
                with Cluster("Foundry AIServices account S0 | no hub", graph_attr=CLUSTER):
                    n_app_foundry_account = CognitiveServices("Microsoft Foundry\nPrivate account endpoint")
                    n_app_foundry_project = Node(
                        "Direct child project: mobility-commercial\n"
                        "sales-fit | marketing-claims | handoff-coordinator\n"
                        "Three pinned agent versions; shared project, NOT unit isolation",
                        shape="box",
                        labelloc="c",
                        width="5.4",
                        height="1.2",
                    )
                    n_app_foundry_model = AzureOpenAI(
                        "Account model deployment\nGPT-4.1 mini | 2025-04-14\nGlobalStandard (provisional)"
                    )
                n_data_blob_fixtures = BlobStorage(
                    "Storage Standard LRS\nPlatform state + separate\nversioned synthetic fixtures"
                )
                n_data_cosmos_state = CosmosDb("Cosmos DB NoSQL\nPrivate agent state\nTopology/RU sizing deferred")
                n_data_search_platform = CognitiveSearch(
                    "AI Search Standard\nPlatform dependency\nNot business retrieval"
                )
                n_sec_keyvault_signing = KeyVaults(
                    "Key Vault Standard\nRSA-2048 / PS256\nNonexportable signing key"
                )
                n_ops_acr_images = ContainerRegistries(
                    "ACR Premium\nPrivate immutable image\nAdmin credentials disabled"
                )

            n_ops_logs_redacted = LogAnalyticsWorkspaces(
                "Log Analytics\nRedacted IDs / timing / usage\nNo routine prompt content"
            )

        n_web_browser_demo >> Edge(label="request: HTTPS UI / API") >> n_edge_apim_gateway
        n_id_entra_audience >> Edge(
            label="auth: gateway MI token\nUnique backend audience", style="dashed", color="#8055a5"
        ) >> n_edge_apim_gateway
        n_edge_apim_gateway >> Edge(label="request: private outbound") >> n_edge_apim_outbound
        n_edge_apim_outbound >> Edge(label="auth: JWT + gateway object ID") >> n_app_aca_backend
        n_app_aca_backend >> Edge(
            label="request / read / sign / pull\nApp MI; scoped RBAC"
        ) >> n_int_pe_services
        n_int_pe_services >> Edge(label="request: project API") >> n_app_foundry_account
        n_int_pe_services >> Edge(label="read: fixture container") >> n_data_blob_fixtures
        n_int_pe_services >> Edge(label="request: sign digest") >> n_sec_keyvault_signing
        n_int_pe_services >> Edge(label="read: image digest") >> n_ops_acr_images
        n_int_pe_services >> Edge(label="private access", style="dashed", color="#8055a5") >> [
            n_data_cosmos_state,
            n_data_search_platform,
        ]
        n_int_dns_zones >> Edge(
            label="config: private resolution", style="dashed", color="#8055a5", constraint="false"
        ) >> n_int_pe_services
        n_app_foundry_account >> Edge(label="contains: direct child") >> n_app_foundry_project
        n_app_foundry_account >> Edge(label="contains: model deployment") >> n_app_foundry_model
        n_app_foundry_project >> Edge(label="request: model inference") >> n_app_foundry_model
        n_app_foundry_project >> Edge(
            label="auth: project MI\nStandard outbound", style="dashed", color="#8055a5"
        ) >> n_app_agent_network
        n_app_agent_network >> Edge(
            label="read / write: platform state\nVia private endpoints / DNS", color="#2368a0"
        ) >> [n_data_blob_fixtures, n_data_cosmos_state, n_data_search_platform]
        [n_edge_apim_gateway, n_app_aca_backend] >> Edge(
            label="telemetry: correlation / errors", style="dotted", color="#737373", constraint="false"
        ) >> n_ops_logs_redacted


if __name__ == "__main__":
    main()
